def seed_focus_image(apps, schema_editor):
    """Use the existing hero photo of the CRTDH building for "Our focus", if there is one and none is set."""
    HomePage = apps.get_model("core", "HomePage")
    HeroSlide = apps.get_model("carousel", "HeroSlide")
    slide = next((s for s in HeroSlide.objects.order_by("id") if "banner10" in (s.image.name or "")), None)
    if not slide:
        return
    for home in HomePage.objects.all():
        if not home.focus_image:
            home.focus_image = slide.image.name
            home.focus_image_alt = home.focus_image_alt or "The building that houses CRTDH at IIT Kharagpur"
            home.save(update_fields=["focus_image", "focus_image_alt"])


